document.getElementById('stage').insertAdjacentHTML('beforeend',"<section class=\"screen ui-paper\" id=\"s16\" data-screen=\"16\">\n  <div class=\"page-index\">16 / OPERATIONS CONSOLE</div>\n  <div class=\"eyebrow\">Operation Center</div>\n  <h1>对社区运营方，平台首先是一套统一的业务运营工具</h1>\n  <div class=\"ops-console\">\n    <div class=\"ops-top\"><div class=\"ops-tabs\"><button class=\"active\" data-ops=\"人才\">人才</button><button data-ops=\"培训\">培训</button><button data-ops=\"企业\">企业</button><button data-ops=\"项目\">项目</button><button data-ops=\"成果\">成果</button></div><div class=\"ops-date\">运营视图 · 演示示意</div></div>\n    <div class=\"ops-metrics\"><div class=\"om known\"><small>首批实训目标</small><b>50</b><span>人</span></div><div class=\"om known\"><small>首批项目交付目标</small><b>≥5</b><span>个</span></div><div class=\"om\"><small>企业需求</small><b>—</b><span>实时统计</span></div><div class=\"om\"><small>孵化项目</small><b>—</b><span>持续积累</span></div></div>\n    <div class=\"ops-body\">\n      <div class=\"ops-panel chart-panel\"><div class=\"panel-head\"><b id=\"opsChartTitle\">人才运营</b><span>目标/结构示意</span></div><div class=\"bar-chart\"><div><span>注册</span><i style=\"--h:88%\"></i></div><div><span>入库</span><i style=\"--h:74%\"></i></div><div><span>实训</span><i style=\"--h:58%\"></i></div><div><span>项目</span><i style=\"--h:36%\"></i></div><div><span>认证</span><i style=\"--h:24%\"></i></div></div></div>\n      <div class=\"ops-panel kanban\"><div class=\"panel-head\"><b>项目运营</b><span>状态视图</span></div><div class=\"kanban-cols\"><div><small>待梳理</small><b>企业需求</b><span></span><span></span></div><div><small>揭榜中</small><b>项目匹配</b><span></span></div><div><small>执行中</small><b>真实项目</b><span></span><span></span><span></span></div><div><small>待验收</small><b>阶段成果</b><span></span></div></div></div>\n      <div class=\"ops-panel todo\"><div class=\"panel-head\"><b>运营待办</b><span>统一审核</span></div><ul><li><i></i>人才入库审核 <em>待处理</em></li><li><i></i>企业认证审核 <em>待处理</em></li><li><i></i>项目中榜确认 <em>待处理</em></li><li><i></i>成果发布审核 <em>待处理</em></li><li><i></i>合规专项审核 <em>待处理</em></li></ul></div>\n    </div>\n    <div class=\"ops-feed\"><span>最新人才</span><span>最新需求</span><span>最新项目</span><span>最新成果</span><small>所有未明确来源的数值均不作为真实运营数据展示</small></div>\n  </div>\n</section>\n<section class=\"screen dark\" id=\"s17\" data-screen=\"17\">\n  <div class=\"page-index\">17 / DATA ASSETS</div>\n  <div class=\"eyebrow\">Long-Term Data Asset</div>\n  <h1>平台持续运营之后，真正沉淀的是四类核心数据资产</h1>\n  <div class=\"data-ecosystem\">\n    <div class=\"data-core\"><small>DATA FOUNDATION</small><strong>数智健康 OPC</strong><b>产业人才数据底座</b><p>为人才推荐、项目匹配、课程优化、产业分析和 OPC 孵化提供数据基础。</p></div>\n    <article class=\"data-island di1\"><div class=\"data-icon\">人</div><h3>人才数据</h3><strong>谁具备什么能力</strong><p>专业背景 · 技能 · 课程 · 项目 · 评价</p><svg viewBox=\"0 0 150 90\"><circle cx=\"30\" cy=\"44\" r=\"15\"/><circle cx=\"80\" cy=\"20\" r=\"7\"/><circle cx=\"115\" cy=\"58\" r=\"9\"/><path d=\"M43 37L73 23M43 49L107 57\"/></svg></article>\n    <article class=\"data-island di2\"><div class=\"data-icon\">需</div><h3>企业需求数据</h3><strong>产业正在需要什么</strong><p>场景 · 技术 · 预算 · 周期 · 问题</p><svg viewBox=\"0 0 150 90\"><rect x=\"19\" y=\"24\" width=\"38\" height=\"42\" rx=\"7\"/><rect x=\"82\" y=\"15\" width=\"49\" height=\"55\" rx=\"7\"/><path d=\"M57 45H82\"/></svg></article>\n    <article class=\"data-island di3\"><div class=\"data-icon\">项</div><h3>项目数据</h3><strong>哪些能力真正能够交付</strong><p>进度 · 成果 · 质量 · 评价</p><svg viewBox=\"0 0 150 90\"><path d=\"M18 66L47 44L76 55L104 28L132 36\"/><circle cx=\"47\" cy=\"44\" r=\"5\"/><circle cx=\"104\" cy=\"28\" r=\"5\"/></svg></article>\n    <article class=\"data-island di4\"><div class=\"data-icon\">果</div><h3>成果孵化数据</h3><strong>哪些项目值得进一步支持</strong><p>案例 · 创业方向 · 市场反馈 · 资源需求</p><svg viewBox=\"0 0 150 90\"><path d=\"M75 74V40M75 48C52 46 40 31 38 15c20 1 34 9 37 26M75 38c20 0 34-10 39-26-21 0-34 9-39 22\"/></svg></article>\n    <svg class=\"data-links\" viewBox=\"0 0 1744 760\"><path d=\"M865 385L336 170M875 385L1408 170M865 402L330 635M879 402L1412 635\"/><circle cx=\"866\" cy=\"391\" r=\"210\"/><circle cx=\"866\" cy=\"391\" r=\"280\"/></svg>\n    <div class=\"data-particles\"><i></i><i></i><i></i><i></i><i></i><i></i><i></i><i></i></div>\n  </div>\n</section>\n<section class=\"screen warm\" id=\"s18\" data-screen=\"18\">\n  <div class=\"page-index\">18 / V1.0 SCOPE</div>\n  <div class=\"eyebrow\">First Release Scope</div>\n  <h1>V1.0 不追求“大而全”，首先跑通核心业务闭环</h1>\n  <div class=\"scope-layout\">\n    <div class=\"scope-core\"><div class=\"scope-center\"><small>V1.0 CORE</small><strong>真实项目闭环</strong><p>第一批人才能够通过平台完成从入库、培训、实训，到承接并交付一个真实产业项目的全过程。</p></div><div class=\"scope-item si1\">社区门户</div><div class=\"scope-item si2\">人才中心</div><div class=\"scope-item si3\">课程与实训</div><div class=\"scope-item si4\">企业需求</div><div class=\"scope-item si5\">揭榜接单</div><div class=\"scope-item si6\">项目交付</div><div class=\"scope-item si7\">评价认证</div><div class=\"scope-item si8\">基础合规</div><div class=\"scope-item si9\">成果展示</div><div class=\"scope-item si10\">运营后台</div><svg viewBox=\"0 0 760 760\"><circle cx=\"380\" cy=\"380\" r=\"225\"/><circle cx=\"380\" cy=\"380\" r=\"315\"/></svg></div>\n    <aside class=\"scope-next\"><small>NEXT PHASE</small><h2>后续增强</h2><div class=\"next-cloud\"><span>导师深度服务</span><span>活动赛事</span><span>工位服务</span><span>政策服务</span><span>算力管理</span><span>投融资</span><span>AI智能匹配</span><span>AI合规预审</span><span>智能体 / Skill</span></div><div class=\"scope-standard\"><b>首期验收业务标准</b><p>不是“功能上线多少个”，而是核心业务链路能否真实跑通。</p></div></aside>\n  </div>\n</section>\n<section class=\"screen paper\" id=\"s19\" data-screen=\"19\">\n  <div class=\"page-index\">19 / ROADMAP & OUTCOMES</div>\n  <div class=\"eyebrow\">Roadmap</div>\n  <h1>从“平台上线”逐步走向“社区运营模式成熟”</h1>\n  <div class=\"phase-roadmap\">\n    <div class=\"phase-line\"></div>\n    <article class=\"phase ph1\"><div class=\"phase-dot\">6</div><small>近期 / 6个月</small><h2>跑通</h2><div class=\"phase-visual\"><span>搭平台</span><span>建体系</span><span>招人才</span><span>接项目</span></div><p>完成首期核心功能，推动首批学员进入实训，并跑通真实产业项目全过程。</p><div class=\"phase-target\"><b>50</b><span>首批学员完成实训</span><i>+</i><b>≥5</b><span>真实项目完成交付</span></div></article>\n    <article class=\"phase ph2\"><div class=\"phase-dot\">12</div><small>中期 / 12个月</small><h2>沉淀</h2><div class=\"phase-visual\"><span>人才库</span><span>案例库</span><span>孵化服务</span><span>项目储备</span></div><p>人才库逐步形成，项目案例持续积累，OPC孵化服务完善，优质创新项目进入储备。</p><div class=\"phase-target\"><b>≥3</b><span>项目进入联合转化基金储备项目库目标</span></div></article>\n    <article class=\"phase ph3\"><div class=\"phase-dot\">36</div><small>长期 / 36个月</small><h2>输出</h2><div class=\"phase-visual\"><span>培养体系</span><span>交付体系</span><span>运营服务</span><span>产业资源</span></div><p>形成成熟社区运营机制，沉淀可复制、可推广的“中医药 + AI OPC”模式。</p><div class=\"phase-target gold\"><b>MODE</b><span>形成可复制、可推广的运营模式</span></div></article>\n  </div>\n</section>\n<section class=\"screen dark\" id=\"s20\" data-screen=\"20\">\n  <div class=\"page-index\">20 / EXPECTED VALUE</div>\n  <div class=\"eyebrow\">Expected Value</div>\n  <h1>平台最终带来的，不只是一个系统</h1>\n  <div class=\"value-constellation\">\n    <div class=\"value-core\"><small>ONE PLATFORM · ONE MECHANISM</small><strong>连接人才与产业</strong><b>连接培训与真实项目</b><p>让平台成为社区持续运营的数字底座</p></div>\n    <article class=\"value v1\"><span>社区</span><h3>可运营</h3><p>人才、课程、需求、项目和成果集中管理。</p></article>\n    <article class=\"value v2\"><span>人才</span><h3>可成长</h3><p>学习、实训和真实项目成为持续积累的能力证明。</p></article>\n    <article class=\"value v3\"><span>企业</span><h3>可交付</h3><p>更容易获得适合自身场景的 AI 人才与项目服务。</p></article>\n    <article class=\"value v4\"><span>园区</span><h3>可连接</h3><p>人才培养直接连接企业需求，产业场景持续反哺培养。</p></article>\n    <article class=\"value v5\"><span>产业</span><h3>可复制</h3><p>不断沉淀人才、项目、成果和运营机制。</p></article>\n    <svg viewBox=\"0 0 1744 720\" class=\"value-lines\"><circle cx=\"872\" cy=\"366\" r=\"198\"/><circle cx=\"872\" cy=\"366\" r=\"282\"/><path d=\"M872 366L312 180M872 366L1438 170M872 366L252 532M872 366L1462 550M872 366L872 677\"/></svg>\n    <div class=\"value-leaf\"><svg viewBox=\"0 0 320 300\"><path d=\"M38 286C128 215 156 130 167 21\"/><path d=\"M142 145c-62 4-91-25-101-62 54 0 89 14 99 45M167 93c56 3 83-28 91-62-47 2-77 18-89 45\"/></svg></div>\n  </div>\n  <div class=\"closing-line\"><span>一批具备 AI 商业交付能力的人才</span><i>×</i><span>一套可运营 · 可量化 · 可复制的模式</span></div>\n  <div class=\"final-slogan\">让人才因项目成长，让产业因人才改变。</div>\n</section>");